let dictionary={en:{appTitle:"Omega Sunlight",settingsTitle:"Settings",latitude:"Latitude",longitude:"Longitude",theme:"Theme",themeSystem:"System",themeLight:"Light",themeDark:"Dark",language:"Language",langSystem:"System",cancel:"Cancel",save:"Save",loading:"Loading data...",chartTitle:"Shortwave Radiation (W/m\xb2)",infoTitle:"Radiation Guide",infoDesc:"Shortwave radiation (W/m\xb2) indicates the intensity of sunlight:",info0:"0: Nighttime",info10:"10-50: Sunrise/sunset, or very dark rainy days",info100:"100-300: Cloudy days",info400:"400-600: Partly cloudy, or sunny days in winter",info700:"700-900: Clear sunny days in spring/autumn",info1000:"1000+: Intense summer sunlight at noon",close:"Close"},ja:{appTitle:"Omega Sunlight",settingsTitle:"設定",latitude:"緯度",longitude:"経度",theme:"テーマ",themeSystem:"システム依存",themeLight:"ライトモード",themeDark:"ダークモード",language:"言語",langSystem:"システム依存",cancel:"キャンセル",save:"保存",loading:"データを読み込み中...",chartTitle:"短波放射量 (W/m\xb2)",infoTitle:"短波放射量の目安",infoDesc:"短波放射量（W/m\xb2）は太陽からの光の強さ（日射量）を示します：",info0:"0: 夜間（太陽が沈んでいる状態）",info10:"10-50: 日の出直後・日没直前、または非常に暗い雨の日",info100:"100-300: 厚い雲に覆われた曇りの日",info400:"400-600: 薄曇りの日、または冬の晴天時",info700:"700-900: 春や秋のよく晴れた日",info1000:"1000+: 真夏の快晴時の正午ごろ（非常に強い日差し）",close:"閉じる"}};export function getLanguage(e){if("system"===e){let t=navigator.language.slice(0,2);return dictionary[t]?t:"en"}return dictionary[e]?e:"en"}export function applyTranslations(e){let t=dictionary[e];document.querySelectorAll("[data-i18n]").forEach(e=>{let n=e.getAttribute("data-i18n");t[n]&&(e.textContent=t[n])})}export function getTranslation(e,t){return dictionary[e]?.[t]||dictionary.en[t]||t}